export function courseCodeFromCourse(value: string) {
  return cleanCourseCode(value);
}

function cleanCourseCode(value: string) {
  return String(value ?? "").trim().match(/[A-Z]{2,5}\d{3}/)?.[0] ?? "";
}

export function fullCourseName(courseSection: string, explicitName?: string) {
  const code = cleanCourseCode(courseSection);
  const mapped = courseNames[code] || "";
  const explicit = String(explicitName ?? "").trim();

  // Prefer the authoritative local course-code map for known courses.
  // Older imported database rows may contain a stale/wrong name (or even
  // the course code itself), which must not override the correct mapping.
  if (mapped) return mapped;
  if (explicit && cleanCourseCode(explicit) !== code) return explicit;
  return code || String(courseSection ?? "").trim();
}

export function displayCourseName(courseSection: string, explicitName?: string) {
  const full = fullCourseName(courseSection, explicitName);
  const raw = String(courseSection ?? "").trim();
  if (!raw || full === raw) return full;
  return `${full} - ${raw}`;
}

export function normalizeSection(value: string) {
  return value.trim().toUpperCase().replace(/[\s-]+/g, "_");
}

export function sectionFromCourse(courseSection: string) {
  const m = courseSection.match(/\((\d+_[A-Z0-9]+)\)/);
  return m?.[1] ?? "";
}

export function baseSection(value: string) {
  return normalizeSection(value).replace(/\d+$/, "");
}

export function codeFromCourse(courseSection: string) {
  return courseSection.split("(")[0];
}
